const INTERNAL_DOMAINS = ['novagentica.ai', 'novagentica.com'];
const t = $input.first().json.data.transcript;

function extractEmail(raw) {
  if (!raw) return null;
  const s = (typeof raw === 'object') ? (raw.email || raw.Email || '') : String(raw);
  const angleMatch = s.match(/<([^>]+@[^>]+)>/);
  return (angleMatch ? angleMatch[1] : s).trim().toLowerCase();
}

const rawParticipants = [...(t.participants || []), t.organizer_email].filter(Boolean);
const flatParticipants = rawParticipants.flatMap(p =>
  typeof p === 'string' ? p.split(',').map(e => e.trim()) : [p]
);
const allEmails = [...new Set(flatParticipants.map(extractEmail).filter(e => e && e.includes('@')))];

const externalEmails = allEmails.filter(e => {
  const domain = e.split('@')[1];
  return domain && !INTERNAL_DOMAINS.includes(domain);
});

const SALES = ['sales','discovery','demo','follow-up','presentation','review','pitch','proposal'];
const mt = (t.summary?.meeting_type || '').toLowerCase();
const isSalesMeetingType = SALES.some(s => mt.includes(s)) || mt === 'unknown' || mt === '';

const organizerEmail = extractEmail(t.organizer_email) || allEmails[0] || '';

return [{ json: {
  meetingId: t.id, meetingTitle: t.title,
  meetingType: t.summary?.meeting_type || 'unknown', isSalesMeetingType,
  transcriptUrl: t.transcript_url, lastCallSummary: t.summary?.overview || '',
  actionItems: t.summary?.action_items || [], gist: t.summary?.gist || '',
  topicsDiscussed: t.summary?.topics_discussed || [], meetingDate: t.dateString,
  duration: t.duration, externalEmails, primaryExternalEmail: externalEmails[0] || null,
  hasExternalAttendees: externalEmails.length > 0,
  allEmails, organizerEmail,
}}];

const contact = $input.first().json;
const companyField = contact.Company;
const companyRelationId = Array.isArray(companyField)
  ? (typeof companyField[0] === 'string' ? companyField[0] : (companyField[0]?.id || null))
  : null;
return [{json:{
  contactId: contact.id, contactName: contact.Name || '',
  contactEmail: contact.Email || '', contactRole: contact.Role || '',
  companyRelationId,
}}];

const result = ($json.results || [])[0];
if (!result) {
  return [{json:{ isCustomer: false, isSupplier: false, reason: 'company_not_found', companyId: null, companyName: null, companyIndustry: null, companyType: '', gDriveFolderUrl: null, slackChannelId: null, companyStatus: '' }}];
}
const props = result.properties || {};
const get = (prop) => {
  if (!prop) return '';
  if (prop.type === 'title') return (prop.title || []).map(t => t.plain_text).join('');
  if (prop.type === 'rich_text') return (prop.rich_text || []).map(t => t.plain_text).join('');
  if (prop.type === 'select') return prop.select?.name || '';
  if (prop.type === 'multi_select') return (prop.multi_select || []).map(s => s.name).join(',');
  if (prop.type === 'url') return prop.url || '';
  return '';
};
const typeStr = get(props['Type']);
const isCustomer = typeStr.includes('Client') || typeStr.includes('Prospect');
const isSupplier = typeStr.includes('Vendor') || typeStr.includes('Investor') || typeStr.includes('Partner');
return [{json:{
  isCustomer, isSupplier,
  reason: isCustomer ? 'customer' : isSupplier ? 'supplier' : 'non_customer_type',
  companyId: result.id,
  companyName: get(props['Name']),
  companyIndustry: get(props['Industry']),
  companyType: typeStr,
  gDriveFolderUrl: get(props['GDrive Folder URL']),
  slackChannelId: get(props['Slack Channel ID']),
  companyStatus: get(props['Status']),
}}];

const items = $input.all();
const STAGE_PRIORITY = {
  'Solution Validation': 5, 'Qualified Opportunity': 4,
  'Strategic Conversation': 3, 'Signed / Expansion': 2,
  'Commercial / Procurement': 1, 'Lead': 0,
};
const validDeals = items.filter(i => i.json.id);
if (validDeals.length === 0) { return [{json:{ hasDeals: false }}]; }
validDeals.sort((a, b) => (STAGE_PRIORITY[b.json.Stage]||0) - (STAGE_PRIORITY[a.json.Stage]||0));
const deal = validDeals[0].json;
const meeting = $('Extract External Attendees').first().json;
const contact = $('Extract Contact Data').first().json;
const company = $('Classify Company Type').first().json;
return [{json:{
  hasDeals: true,
  meetingId: meeting.meetingId, meetingTitle: meeting.meetingTitle,
  meetingType: meeting.meetingType, isSalesMeetingType: meeting.isSalesMeetingType,
  transcriptUrl: meeting.transcriptUrl, lastCallSummary: meeting.lastCallSummary,
  actionItems: meeting.actionItems, gist: meeting.gist,
  topicsDiscussed: meeting.topicsDiscussed, meetingDate: meeting.meetingDate,
  duration: meeting.duration, externalEmails: meeting.externalEmails,
  contactId: contact.contactId, contactName: contact.contactName,
  contactEmail: contact.contactEmail, contactRole: contact.contactRole,
  companyId: company.companyId, companyName: company.companyName,
  companyIndustry: company.companyIndustry, gDriveFolderUrl: company.gDriveFolderUrl,
  slackChannelId: company.slackChannelId,
  dealId: deal.id, dealName: deal.Name, dealStage: deal.Stage,
  dealType: deal['Deal Type'], champion: deal.Champion || '',
  economicBuyer: deal['Economic Buyer'] || '', closeDate: deal['Close Date'] || '',
}}];

const t = $input.first().json;
const title = (t.meetingTitle || '').toLowerCase();
const meetingType = (t.meetingType || '').toLowerCase();
const duration = t.duration || 0;
const actionItemsList = Array.isArray(t.actionItems)
  ? t.actionItems.join('\n')
  : (t.actionItems || '');

let category;
if (title.includes('1:1') || title.includes('one on one') || title.includes('one-on-one')) {
  category = '1:1';
} else if (title.includes('standup') || title.includes('stand-up') || (title.includes('daily') && duration <= 20)) {
  category = 'Standup';
} else if (title.includes('all hands') || title.includes('all-hands') || title.includes('allhands')) {
  category = 'All-hands';
} else if (title.includes('retro') || title.includes('retrospective')) {
  category = 'Retrospective';
} else if (title.includes('interview')) { category = 'Interview';
} else if (title.includes('board')) { category = 'Board';
} else if (title.includes('strategy') || title.includes('planning') || title.includes('roadmap') || title.includes('okr')) {
  category = 'Strategy';
} else if (title.includes('training') || title.includes('onboarding') || title.includes('workshop')) {
  category = 'Training';
} else if (title.includes('sync') || title.includes('weekly') || title.includes('team') || meetingType.includes('team')) {
  category = 'Team sync';
} else if (meetingType.includes('1:1') || meetingType.includes('one on one')) {
  category = '1:1';
} else if (duration > 0 && duration <= 15) { category = '1:1';
} else { category = 'Internal'; }

const EMAIL_TO_NAME = {
  'shiv@novagentica.com': 'Shiv Tailor',
  'maru@novagentica.com': 'Maru Winnacker',
  'felix@novagentica.com': 'Felix Bühner',
  'martin@novagentica.com': 'Martin Hofmann',
  'helmuth@novagentica.com': 'Helmuth Zimmermann',
  'luuk@novagentica.com': 'Luuk',
  'elmundo@novagentica.com': 'Elmundo',
};
const EMAIL_TO_NOTION_ID = {
  'shiv@novagentica.com': '368d872b-594c-81c6-9d9d-00027c18626e',
  'maru@novagentica.com': '36bd872b-594c-8187-8fd1-0002a5b3b26b',
  'felix@novagentica.com': '36bd872b-594c-81dd-9f41-0002d2c5e485',
  'martin@novagentica.com': '2cbd872b-594c-81e6-8f6e-0002348d1677',
  'helmuth@novagentica.com': '36bd872b-594c-8104-990b-00027d6ae729',
  'luuk@novagentica.com': '37ad872b-594c-81de-aa92-00028a4acf58',
  'elmundo@novagentica.com': '36bd872b-594c-8151-8973-00023a14ae6f',
};
const allEmails = t.allEmails || [];
const attendeeNames = [...new Set(allEmails.map(e => EMAIL_TO_NAME[e] || e))];
const attendeeNotionIds = [...new Set(allEmails.map(e => EMAIL_TO_NOTION_ID[e]).filter(Boolean))];
const hostName = EMAIL_TO_NAME[t.organizerEmail] || t.organizerEmail || '';
const hostNotionId = EMAIL_TO_NOTION_ID[t.organizerEmail] || null;

function formatActionItems(raw) {
  if (!raw) return '';
  const lines = [];
  let currentPerson = null;
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    const nameMatch = trimmed.match(/^\*\*(.+?)\*\*$/);
    if (nameMatch) { currentPerson = nameMatch[1].trim();
    } else if (trimmed && currentPerson) {
      const action = trimmed.replace(/\s*\(\d+:\d+\)\s*$/, '').trim();
      if (action) lines.push('• ' + action + ' — ' + currentPerson);
    }
  }
  return lines.join('\n');
}

function truncate2000(str) {
  if (str.length <= 2000) return str;
  const cut = str.lastIndexOf('\n', 1990);
  return (cut > 0 ? str.slice(0, cut) : str.slice(0, 1990)) + '\n…';
}

const actionItemsFormatted = truncate2000(formatActionItems(actionItemsList));

return [{ json: {
  meetingId: t.meetingId, meetingTitle: t.meetingTitle, meetingDate: t.meetingDate,
  transcriptUrl: t.transcriptUrl || '', overview: t.lastCallSummary || '',
  gist: t.gist || '', actionItems: actionItemsList, actionItemsFormatted,
  newSummary: t.lastCallSummary || '', internalMeetingCategory: category,
  allEmails, attendeeNames, attendeeNotionIds, hostName, hostNotionId,
}}];

// Look back 12 hours — Fireflies fromDate filters by meeting date, not processing date.
// Meetings can take 15-45 min to process, so a short window misses them.
const fromDate = new Date(Date.now() - 12 * 60 * 60 * 1000).toISOString();
return [{ json: { fromDate } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processedMeetingIds) staticData.processedMeetingIds = [];
if (staticData.processedMeetingIds.length > 1000) {
  staticData.processedMeetingIds = staticData.processedMeetingIds.slice(-1000);
}

const allItems = $input.all();
const newItems = allItems.filter(item => {
  const id = item.json.id;
  return id && !staticData.processedMeetingIds.includes(id);
});

newItems.forEach(item => {
  if (item.json.id) staticData.processedMeetingIds.push(item.json.id);
});

if (newItems.length === 0) return [];

return newItems.map(item => ({ json: { ...item.json } }));

