const actionTag = '[ACTION ITEMS]';
const decisionsTag = '[DECISIONS]';
const actionStart = text.indexOf(actionTag);
const decisionsStart = text.indexOf(decisionsTag);
let actionItemsText = '';
let decisionsText = '';
if (actionStart !== -1) {
  const end = decisionsStart !== -1 ? decisionsStart : text.length;
  actionItemsText = text.slice(actionStart + actionTag.length, end).trim();
} else { actionItemsText = text.trim(); }
if (decisionsStart !== -1) {
  decisionsText = text.slice(decisionsStart + decisionsTag.length).trim();
}
return [{ json: { actionItemsText, decisionsText } }];

const meetingPageId = $('Create Meeting Record').first().json.id || '';
