const meetingPageId = $('Create Meeting Record').first().json.id || '';
const decisionsText = ($('Extract Meeting Sections').first().json.decisionsText || '').trim();
if (!decisionsText) return [];
const decisions = [];
for (const line of decisionsText.split('\n')) {
  const trimmed = line.trim().replace(/^[•\-]\s*/, '').trim();
  if (trimmed && !trimmed.toLowerCase().includes('no decisions recorded')) {
    decisions.push({ json: { title: trimmed, meetingPageId } });
  }
}
return decisions;

const raw = $input.first().json;
const text = (raw.content && raw.content[0] && raw.content[0].text) || raw.text || '';
let category = 'unknown';
try {
  const m = text.match(/\{[^}]+\}/);
  if (m) { const p = JSON.parse(m[0]); category = p.category || 'unknown'; }
} catch(e) {}
const prev = $('Classify Company Type').first().json;
return [{ json: { ...prev, category } }];

const c = $('Classify Company Type').first().json;
const m = $('Extract External Attendees').first().json;
const contact = $('Extract Contact Data').first().json || {};
function extractText(ai){
  if (ai == null) return '';
  if (typeof ai === 'string') return ai;
  if (typeof ai.text === 'string') return ai.text;
  if (typeof ai.completion === 'string') return ai.completion;
  if (typeof ai.output === 'string') return ai.output;
  if (typeof ai.response === 'string') return ai.response;
  if (typeof ai.message === 'string') return ai.message;
  if (ai.message && typeof ai.message.content === 'string') return ai.message.content;
  if (Array.isArray(ai.content)) return ai.content.map(x => (x && typeof x.text==='string') ? x.text : (typeof x==='string'?x:'')).join('');
  if (typeof ai.content === 'string') return ai.content;
  try { return JSON.stringify(ai); } catch(e){ return ''; }
}
const raw = extractText($input.first().json);
let parsed = {};
try { let s = String(raw).replace(/```json/gi,'').replace(/```/g,'').trim(); const a=s.indexOf('{'); const b=s.lastIndexOf('}'); if(a!==-1&&b!==-1) s=s.slice(a,b+1); parsed=JSON.parse(s); } catch(e){ parsed={}; }
if(!parsed.category){ const cm=String(raw).match(/"category"\s*:\s*"([A-Za-z]+)"/i); if(cm) parsed.category=cm[1]; }
if(parsed.confidence===undefined||parsed.confidence===null){ const fm=String(raw).match(/"confidence"\s*:\s*([0-9.]+)/); if(fm) parsed.confidence=parseFloat(fm[1]); }
if(!parsed.reasoning){ const rm=String(raw).match(/"reasoning"\s*:\s*"([^"]*)/); if(rm) parsed.reasoning=rm[1]; }
const VALID=['SALES','VENDOR','PARTNER','INVESTOR','OTHER'];
let category=String(parsed.category||'').toUpperCase().trim();
if(!VALID.includes(category)) category='OTHER';
let confidence=Number(parsed.confidence);
if(!isFinite(confidence)) confidence=0;
const reasoning=String(parsed.reasoning||'').slice(0,500);
const NOTION_TYPE={SALES:'Sales call',VENDOR:'Vendor',PARTNER:'Partner',INVESTOR:'Investor',OTHER:'Other'};
const EMOJI={SALES:'💰',VENDOR:'🧾',PARTNER:'🤝',INVESTOR:'📈',OTHER:'❓'};
const crmType=c.companyType||'';
const crmMissing=!crmType||c.reason==='company_not_found';
let crmCategory='';
if(crmType.includes('Client')||crmType.includes('Prospect')) crmCategory='SALES';
else if(crmType.includes('Vendor')) crmCategory='VENDOR';
else if(crmType.includes('Partner')) crmCategory='PARTNER';
else if(crmType.includes('Investor')) crmCategory='INVESTOR';
const agree=crmMissing||!crmCategory||crmCategory===category;
const needsReview=!agree||confidence<0.6;
return [{ json: { ...c, category, confidence, reasoning, notionType:NOTION_TYPE[category], categoryEmoji:EMOJI[category], crmType, crmCategory, crmMissing, agree, needsReview, rawClassifier:String(raw).slice(0,300), meetingId:m.meetingId, meetingTitle:m.meetingTitle, meetingDate:m.meetingDate, transcriptUrl:m.transcriptUrl, lastCallSummary:m.lastCallSummary, gist:m.gist, primaryExternalEmail:m.primaryExternalEmail, externalEmails:m.externalEmails, contactId:contact.contactId||null, contactName:contact.contactName||'' } }];
